请对以下 case 进行三维加权评分。

=== case_id ===
Case-08-sleep-005

=== 用户原始指令 (query.txt) ===
搞个睡眠卡片,顶部一行带数字的话,点哪个跳app,读日历,提醒我快撑不住

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "搞个睡眠卡片,顶部一行带数字的话,点哪个跳app,读日历,提醒我快撑不住",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.settings",
        "abilityName": "com.huawei.hmos.settings.MainAbility",
        "uri": "intelligent_scene_entry"
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "calendar": {
        "type": "object",
        "description": "日历能力返回的今日日程结果。",
        "sampleValue": {
          "items": [
            {
              "entityId": "calendar-demo-001",
              "title": "07:30 早会",
              "dtStart": "07:30",
              "dtEnd": "08:00"
            },
            {
              "entityId": "calendar-demo-002",
              "title": "09:00 站会",
              "dtStart": "09:00",
              "dtEnd": "09:20"
            }
          ]
        },
        "properties": {
          "items": {
            "type": "array",
            "description": "今日日历日程列表，用于判断还有多少安排以及展示下一条日程。",
            "sampleValue": [
              {
                "entityId": "calendar-demo-001",
                "title": "07:30 早会",
                "dtStart": "07:30",
                "dtEnd": "08:00"
              },
              {
                "entityId": "calendar-demo-002",
                "title": "09:00 站会",
                "dtStart": "09:00",
                "dtEnd": "09:20"
              }
            ],
            "items": {
              "type": "object",
              "description": "单条日历日程。",
              "sampleValue": {
                "entityId": "calendar-demo-001",
                "title": "07:30 早会",
                "dtStart": "07:30",
                "dtEnd": "08:00"
              },
              "properties": {
                "entityId": {
                  "type": "string",
                  "description": "日程唯一标识符。",
                  "sampleValue": "calendar-demo-001"
                },
                "title": {
                  "type": "string",
                  "description": "日程标题。",
                  "sampleValue": "07:30 早会"
                },
                "dtStart": {
                  "type": "string",
                  "description": "日程开始时间，当天日程通常为 HH:MM。",
                  "sampleValue": "07:30"
                },
                "dtEnd": {
                  "type": "string",
                  "description": "日程结束时间，当天日程通常为 HH:MM。",
                  "sampleValue": "08:00"
                }
              }
            }
          }
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_sleep.png",
      "description": "睡眠监督图标，适合用于睡眠提醒、休息状态和夜间场景识别。"
    }
  ]
}

